package com.zerostreams.app;
import android.content.Context;import android.os.*;import android.net.Uri;import java.io.File;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import androidx.media3.common.*;import androidx.media3.exoplayer.ExoPlayer;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class MediaFiles {
 static String identify(byte[] bytes){if(bytes.length<12)return null;String atom=new String(bytes,4,4,java.nio.charset.StandardCharsets.US_ASCII);if(atom.equals("ftyp"))return new String(bytes,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("qt  ")?"mov":"mp4";if((bytes[0]&255)==0x1a&&(bytes[1]&255)==0x45&&(bytes[2]&255)==0xdf&&(bytes[3]&255)==0xa3)return new String(bytes,java.nio.charset.StandardCharsets.US_ASCII).contains("webm")?"webm":"mkv";if(new String(bytes,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")&&new String(bytes,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("AVI "))return "avi";if(new String(bytes,0,3,java.nio.charset.StandardCharsets.US_ASCII).equals("FLV"))return "flv";if((bytes[0]&255)==0x47)return "ts";if(bytes[0]==0&&bytes[1]==0&&bytes[2]==1&&(bytes[3]&255)==0xba)return "mpg";return null;}
 static String mime(String format){return format.equals("mkv")?"video/x-matroska":format.equals("webm")?"video/webm":format.equals("mov")?"video/quicktime":format.equals("ts")?"video/mp2t":format.equals("mpg")?"video/mpeg":format.equals("flv")?"video/x-flv":format.equals("avi")?"video/x-msvideo":"video/mp4";}
 static boolean playable(Context context,File file,String format)throws Exception{CountDownLatch done=new CountDownLatch(1);AtomicBoolean result=new AtomicBoolean();AtomicReference<ExoPlayer> reference=new AtomicReference<>();Handler handler=new Handler(Looper.getMainLooper());handler.post(()->{try{ExoPlayer player=new ExoPlayer.Builder(context).build();reference.set(player);player.setVolume(0);player.setPlayWhenReady(false);player.addListener(new Player.Listener(){@Override public void onPlayerError(PlaybackException error){done.countDown();}@Override public void onPlaybackStateChanged(int state){if(state!=Player.STATE_READY)return;boolean video=false,audio=false,hasAudio=false;for(Tracks.Group group:player.getCurrentTracks().getGroups()){if(group.getType()==C.TRACK_TYPE_AUDIO)hasAudio=true;for(int i=0;i<group.length;i++)if(group.isTrackSupported(i)){if(group.getType()==C.TRACK_TYPE_VIDEO)video=true;if(group.getType()==C.TRACK_TYPE_AUDIO)audio=true;}}result.set(video&&(!hasAudio||audio));done.countDown();}});player.setMediaItem(new MediaItem.Builder().setUri(Uri.fromFile(file)).setMimeType(mime(format)).build());player.prepare();}catch(Exception ignored){done.countDown();}});try{return done.await(20,TimeUnit.SECONDS)&&result.get();}finally{handler.post(()->{ExoPlayer player=reference.getAndSet(null);if(player!=null)player.release();});}}
}
